{"implementation": "def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    n = len(lengths)
    if not isinstance(lengths, list) or not isinstance(scores, list) or not isinstance(budget, int):
        raise ValueError("Invalid input")
    if len(lengths) != len(scores):
        raise ValueError("Mismatched lengths")
    if budget < 0 or any(l < 0 for l in lengths):
        raise ValueError("Negative values")
    INF_NEG = float('-inf')
    dp = [(INF_NEG, 0, ()) for _ in range(budget+1)]
    dp[0] = (0.0, 0, ())
    for i in range(1, n+1):
        l = lengths[i-1]
        s = scores[i-1]
        new_dp = [(INF_NEG, 0, ()) for _ in range(budget+1)]
        for w in range(budget+1):
            best = dp[w]
            if w >= l and dp[w-l][0] != INF_NEG:
                take_score = dp[w-l][0] + s
                take_neg_tokens = dp[w-l][1] - l
                take_indices = dp[w-l][2] + (i-1,)
                take = (take_score, take_neg_tokens, take_indices)
                if (take_score > best[0] or (take_score == best[0] and take_neg_tokens > best[1]) or (take_score == best[0] and take_neg_tokens == best[1] and take_indices < best[2])):
                    best = take
            new_dp[w] = best
        dp = new_dp
    best = None
    for w in range(budget+1):
        if dp[w][0] == INF_NEG:
            continue
        if best is None:
            best = dp[w]
        else:
            cur = dp[w]
            if (cur[0] > best[0] or (cur[0] == best[0] and cur[1] > best[1]) or (cur[0] == best[0] and cur[1] == best[1] and cur[2] < best[2])):
                best = cur
    selected_indices = list(best[2])
    used_tokens = -best[1]
    summed_score = best[0]
    return {"selected_indices": selected_indices, "used_tokens": used_tokens, "summed_score": summed_score}"}
